{"cards": [{"node_code": "N_919ce206907f8c7d", "definition": "研究利用多源数据感知城市交通状态、分析时空演化规律及进行城市级智能计算的技术领域，涵盖活动感知、状态分析与智能决策支持。", "boundary": "本节点聚焦于城市交通的“数据感知”与“智能计算”技术层面。若内容侧重具体的交通规划方案或政策制定，归入城市移动性规划或城市交通治理；若侧重纯算法理论而非交通应用，归入交通运输系统工程。本节点强调“城市级”宏观视角及“全息”多源数据融合，区别于单一设施或微观车辆控制。", "includes": ["城市居民活动与空间移动的多源数据感知技术", "城市交通流、拥堵等状态的时空演化分析与预测", "面向城市交通管理的智能计算模型与决策支持系统"], "excludes": ["具体的交通规划方案设计与评估（归入城市移动性规划）", "交通政策法规、管理体制及多主体协同机制（归入城市交通治理）", "纯数学算法或通用人工智能理论（归入交通运输系统工程或计算机类）"], "sibling_distinctions": [{"other_code": "N_7bc16b66bc23538a", "rule": "本节点侧重感知技术与智能计算工具；兄弟节点侧重基于这些工具进行的规划方案、出行需求管理及空间布局优化。"}, {"other_code": "N_51de52d9ce12c1b0", "rule": "本节点侧重技术实现与数据分析；兄弟节点侧重治理机制、政策制定、法律法规及多主体协调。"}], "cross_boundary_rule": "涉及感知技术的具体算法实现归入本节点；涉及基于感知结果的规划决策归入城市移动性规划；涉及基于感知结果的制度设计归入城市交通治理。"}, {"node_code": "N_51de52d9ce12c1b0", "definition": "研究城市交通领域的公共政策、法律法规、多主体协同机制及数智化治理模式的领域，旨在优化交通管理效能与社会公平。", "boundary": "本节点聚焦于城市交通的“治理”层面，即制度、政策、法律及组织管理。若内容侧重具体的交通规划技术或智能算法，归入城市移动性规划或全息感知节点；若侧重交通运营服务流程，归入城市交通服务与运营。本节点强调政府、企业、公众等多方主体的互动与规则制定。", "includes": ["城市交通公共政策制定、评估及交通需求管理政策", "城市交通相关法律法规、标准及合规性研究", "政府、企业、公众等多主体协同治理机制及数智化治理模式"], "excludes": ["具体的交通网络规划、线路设计或技术方案（归入城市移动性规划）", "交通感知技术、数据分析算法或智能计算模型（归入城市交通全息感知与智能计算）", "具体的公交、共享交通等运营服务流程与调度（归入城市交通服务与运营或城市共享交通）"], "sibling_distinctions": [{"other_code": "N_7bc16b66bc23538a", "rule": "本节点侧重治理制度、政策与法律；兄弟节点侧重规划方法、出行行为分析及空间布局优化。"}, {"other_code": "N_919ce206907f8c7d", "rule": "本节点侧重治理机制与政策工具；兄弟节点侧重支撑治理的数据感知与智能计算技术。"}], "cross_boundary_rule": "涉及政策制定的技术支撑（如仿真）可关联全息感知，但政策本身归入本节点；涉及规划实施的管理归入本节点，规划方案归入移动性规划。"}, {"node_code": "N_12f37b4d1e611b05", "definition": "研究城市范围内共享交通模式（如网约车、共享单车、顺风车等）的服务组织、平台运营、资源配置及用户体验的领域。", "boundary": "本节点聚焦于“共享”这一特定交通模式在城市中的组织与运营。若内容侧重宏观交通规划或政策治理，归入城市移动性规划或城市交通治理；若侧重传统公共交通（如公交、地铁）的运营，归入城市交通服务与运营。本节点强调资产共享、平台经济特征及动态供需匹配。", "includes": ["共享出行、共享车辆等模式的服务组织与流程设计", "共享交通平台的运营策略、定价机制及供需匹配", "共享交通在城市交通系统中的定位、整合及用户体验研究"], "excludes": ["传统公共交通（公交、地铁、有轨电车）的运营与管理（归入城市交通服务与运营）", "共享交通的宏观政策制定、法律法规及多主体治理（归入城市交通治理）", "共享交通的纯算法优化或感知技术（归入城市交通全息感知与智能计算）"], "sibling_distinctions": [{"other_code": "N_ec134471ef5e91cb", "rule": "本节点侧重共享模式（资产/使用权共享）；兄弟节点侧重传统公共交通及一般性交通服务流程。"}, {"other_code": "N_51de52d9ce12c1b0", "rule": "本节点侧重共享交通的业务运营与服务组织；兄弟节点侧重针对共享交通的政策、法规及治理机制。"}], "cross_boundary_rule": "涉及共享交通的运营策略归入本节点；涉及共享交通的监管政策归入城市交通治理；涉及共享交通的算法调度归入全息感知或系统工程。"}]}
